#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    bool insideParentheses = false;
    string buffer;
    int maxOutsideLength = 0;
    int insideCount = 0;
    for (int i = 0; i < n; i++) {
        char c = s[i];
        if (c == '(') {
            if (!insideParentheses) {
                vector<string> outsideWords;
                stringstream ss(buffer);
                string word;
                while (getline(ss, word, '_')) {
                    outsideWords.push_back(word);
                }
                for (const auto& w : outsideWords) {
                    maxOutsideLength = max(maxOutsideLength, (int)w.length());
                }
            }
            insideParentheses = true;
            buffer.clear();
        } else if (c == ')') {
            insideParentheses = false;
            vector<string> insideWords;
            stringstream ss(buffer);
            string word;
            while (getline(ss, word, '_')) {
                if (!word.empty()) {
                    insideCount++;
                }
            }
            buffer.clear();
        } else {
            buffer += c;
        }
    }
    vector<string> outsideWords;
    stringstream ss(buffer);
    string word;
    while (getline(ss, word, '_')) {
        outsideWords.push_back(word);
    }
    for (const auto& w : outsideWords) {
        maxOutsideLength = max(maxOutsideLength, (int)w.length());
    }
    cout << maxOutsideLength << " " << insideCount << "\n";
    return 0;
}
